import{_ as a,o as r,c as t,a6 as o}from"./chunks/framework.O8w_gp-L.js";const f=JSON.parse('{"title":"Forge and gear","description":"","frontmatter":{},"headers":[],"relativePath":"guides/forge.md","filePath":"guides/forge.md"}'),n={name:"guides/forge.md"};function s(i,e,l,g,d,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="forge-and-gear" tabindex="-1">Forge and gear <a class="header-anchor" href="#forge-and-gear" aria-label="Permalink to &quot;Forge and gear&quot;">​</a></h1><p>The <strong>Forge</strong> opens after <strong>1-1 Water Gate Steps</strong>. Your first forged weapon is always at least <strong>Rare</strong>.</p><h2 id="gear-slots" tabindex="-1">Gear slots <a class="header-anchor" href="#gear-slots" aria-label="Permalink to &quot;Gear slots&quot;">​</a></h2><ul><li><strong>Weapon, Hood, Coat, Gloves, Boots</strong> and the <strong>Spindle</strong></li><li>The Spindle&#39;s line can be changed at the forge with <strong>Respin</strong>.</li></ul><p><strong>Rarities</strong> (low to high)</p><ul><li><strong>Plain → Fine → Rare → Heirloom</strong></li></ul><h2 id="forging" tabindex="-1">Forging <a class="header-anchor" href="#forging" aria-label="Permalink to &quot;Forging&quot;">​</a></h2><ul><li>Recipes use raw materials: ore, creature hide, timber, flax and crystal, plus a little silver.</li><li>Short of something? The forge shows where to find it: a stage, the Gathering Hall, or a later chapter.</li></ul><h2 id="forge-tiers" tabindex="-1">Forge tiers <a class="header-anchor" href="#forge-tiers" aria-label="Permalink to &quot;Forge tiers&quot;">​</a></h2><ul><li><strong>Band 1:</strong> after 1-1</li><li><strong>Band 10:</strong> after 1-5</li><li><strong>Band 20:</strong> after 3-5</li><li><strong>Band 30:</strong> after 5-5</li><li><strong>Band 40:</strong> at Lv 40, once band 30 is open</li></ul><h2 id="gear-names-by-band" tabindex="-1">Gear names by band <a class="header-anchor" href="#gear-names-by-band" aria-label="Permalink to &quot;Gear names by band&quot;">​</a></h2><ul><li>Band 1: <strong>Hushwood</strong></li><li>Band 10: <strong>Ironbound</strong></li><li>Band 20: <strong>Bellwood</strong></li><li>Band 30: <strong>Thornbriar</strong></li><li>Band 40 and up: <strong>Tempered</strong></li></ul><h2 id="binding" tabindex="-1">Binding <a class="header-anchor" href="#binding" aria-label="Permalink to &quot;Binding&quot;">​</a></h2><p>Gear binds to you the first time you wear it. The game asks first: <strong>Wear</strong> it?</p><h2 id="salvage-and-thread-dust" tabindex="-1">Salvage and Thread Dust <a class="header-anchor" href="#salvage-and-thread-dust" aria-label="Permalink to &quot;Salvage and Thread Dust&quot;">​</a></h2><p>Salvage gear you don&#39;t need in town for <strong>Thread Dust</strong>: 1 for Plain, 2 Fine, 4 Rare, 8 Heirloom. Gear can&#39;t be sold to shops.</p><p><strong>Wayline Shards</strong> (from Lv 30) Shards thread extra power into your gear at the forge, with Thread Dust helping pay. You get them from boss stages, Hard elites, level rewards from 31 to 50 and the weekly prize.</p><h2 id="more-gear" tabindex="-1">More gear <a class="header-anchor" href="#more-gear" aria-label="Permalink to &quot;More gear&quot;">​</a></h2><p>Finish all three <strong>weekly goals</strong> for a Rare-or-better piece.</p><p>Show off your gear in &lt;#SHOWCASE&gt;!</p>',20)])])}const p=a(n,[["render",s]]);export{f as __pageData,p as default};
